{var $v_title = ($p['title'] ?? null)}
{var $v_label = ($p['label'] ?? null)}
{var $v_lines = ($p['lines'] ?? null)}
{var $v_shape = ($p['shape'] ?? 'cards')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_9}
  {capture $c_8}
    {if ui_t(ui_eq($v_shape, 'cards'))}
      {capture $c_2}
        {foreach ui_l($v_lines) as $v_l}
          {capture $c_1}
            {=ui_include('ui/skeleton/skeleton.latte', ['p' => ['Class' => 'aspect-video w-full']])|noescape}
            {=ui_include('ui/skeleton/skeleton.latte', ['p' => ['Class' => 'h-4 w-2/3']])|noescape}
            {=ui_include('ui/skeleton/skeleton.latte', ['p' => ['Class' => 'h-4 w-full']])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Class' => 'rounded bg-card inset-ring inset-ring-border p-4', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_1])|noescape}
        {/foreach}
      {/capture}
      {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => '1-3', 'Class' => 'gap-4'], 'children' => $c_2])|noescape}
    {elseif ui_t(ui_eq($v_shape, 'list'))}
      {capture $c_5}
        {foreach ui_l($v_lines) as $v_l}
          {capture $c_4}
            {=ui_include('ui/skeleton/skeleton.latte', ['p' => ['Class' => 'size-10 shrink-0 rounded-full']])|noescape}
            {capture $c_3}
              {=ui_include('ui/skeleton/skeleton.latte', ['p' => ['Class' => 'h-4 w-1/3']])|noescape}
              {=ui_include('ui/skeleton/skeleton.latte', ['p' => ['Class' => 'h-4 w-full']])|noescape}
            {/capture}
            {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => 'flex-1'], 'children' => $c_3])|noescape}
          {/capture}
          {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'center', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_4])|noescape}
        {/foreach}
      {/capture}
      {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch'], 'children' => $c_5])|noescape}
    {else}
      {capture $c_7}
        {=ui_include('ui/skeleton/skeleton.latte', ['p' => ['Class' => 'h-8 w-3/4']])|noescape}
        {foreach ui_l($v_lines) as $v_l}
          {capture $c_6}
            {=ui_include('ui/skeleton/skeleton.latte', ['p' => ['Class' => 'h-4 w-full']])|noescape}
            {=ui_include('ui/skeleton/skeleton.latte', ['p' => ['Class' => 'h-4 w-5/6']])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_6])|noescape}
        {/foreach}
      {/capture}
      {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch', 'Class' => 'mx-auto max-w-2xl'], 'children' => $c_7])|noescape}
    {/if}
  {/capture}
  {=ui_include('ui/block/block.latte', ['p' => ['Tag' => 'div', 'Class' => 'w-full', 'Attrs' => ui_attrs(['role', 'status', 'aria-label', $v_label, 'data-testid', 'skeleton', 'data-shape', $v_shape])], 'children' => $c_8])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_9])|noescape}
